action_details.action_postfix:
taxpayer.military_retirement_pay /result.ct_military_retirement_exclusion xdef


taxpayer.sbp_payments 0 gt
{
  taxpayer.sbp_payments /result.ct_sbp_exclusion xdef
} if


taxpayer.military_drill_pay 0 gt
{
  taxpayer.military_drill_pay /result.ct_guard_reserve_exclusion xdef
} if


result.ct_military_retirement_exclusion result.ct_sbp_exclusion add result.ct_guard_reserve_exclusion add
/result.ct_total_military_exclusion xdef


result.agi result.ct_total_military_exclusion sub 0 max
/result.ct_adjusted_agi xdef


"Connecticut military retirement exclusion: $" result.ct_military_retirement_exclusion cvs strconcat job.audit_trail swap addto
result.ct_sbp_exclusion 0 gt
{
  "Connecticut SBP exclusion: $" result.ct_sbp_exclusion cvs strconcat job.audit_trail swap addto
} if
result.ct_guard_reserve_exclusion 0 gt
{
  "Connecticut Guard/Reserve pay exclusion: $" result.ct_guard_reserve_exclusion cvs strconcat job.audit_trail swap addto
} if
"Connecticut total military exclusion: $" result.ct_total_military_exclusion cvs strconcat job.audit_trail swap addto
